def boundedKnapsack(weights, values, counts, capacity):
    best = [0] * (capacity + 1)
    for w, v, c in zip(weights, values, counts):
        size = 1
        while c > 0:
            take = min(size, c)
            c -= take
            size *= 2
            bw, bv = w * take, v * take
            if bw > capacity:
                continue
            best = best[:bw] + [max(a, b + bv) for a, b in zip(best[bw:], best)]
    return best[capacity]
